  "settings.magicPrompts.page.group.planImprove.title": "Поліпшити план",
  "settings.magicPrompts.page.group.planImprove.description": "Прихований промпт, який використовується під час надсилання збереженого плану в потік покращення.",
  "settings.magicPrompts.page.group.planTodo.title": "Планування Todo",
  "settings.magicPrompts.page.group.planTodo.description": "Прихований промпт, який використовується під час надсилання завдання до нового сесії планування.",
  "settings.magicPrompts.page.group.planImplement.title": "Реалізувати план",
  "settings.magicPrompts.page.group.planImplement.description": "Прихований промпт, який використовується під час надсилання збереженого плану в потік реалізації.",
  "settings.magicPrompts.page.group.sessionSummary.title": "Підсумок сесії",
  "settings.magicPrompts.page.group.sessionSummary.description": "Промпти, які використовуються командою /summary: видиме повідомлення користувача + приховані інструкції. Неруйнівний – не стискає історію сесії.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.title": "Огляд робочого простору",
  "settings.magicPrompts.page.group.sessionExplore.title": "Огляд кодової бази",
  "settings.magicPrompts.page.group.sessionExplore.description": "Промпти, які використовуються командою /explore: видиме повідомлення користувача + приховані інструкції. Досліджує репозиторій і дає структуровану орієнтацію — загальна картина, основні модулі, як вони пов'язані й звідки почати — а не дамп файл за файлом.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.description": "Промпти, які використовуються командою /workspace-review: видиме повідомлення користувача + приховані інструкції. Перевіряє diff робочого простору — чи досягнуто наміру і чи реалізація коректна й адекватна, класифікуючи знахідки за рівнем критичності.",
  "settings.magicPrompts.page.group.sessionFeaturePlan.title": "Планування фічі",
  "settings.magicPrompts.page.group.sessionFeaturePlan.description": "Промпти, які використовуються командою /plan-feature: видиме повідомлення користувача + приховані інструкції. Запускає кероване діалогове планування — досліджує код і ставить уточнюючі запитання невеликими батчами, перш ніж скласти план імплементації.",
  "settings.magicPrompts.page.group.sessionCatchUp.title": "Повернення в контекст",
  "settings.magicPrompts.page.group.sessionCatchUp.description": "Промпти, які використовуються командою /catch-up: видиме повідомлення користувача + приховані інструкції. Будує контекст з урахуванням гілки — коміти гілки, її PR і незакомічену роботу разом — щоб зрозуміти, що ти робив, а тоді дає легкозасвоюваний підсумок і продуктовий наступний крок.",
  "settings.magicPrompts.page.group.sessionDebug.title": "Дебаг",
  "settings.magicPrompts.page.group.sessionDebug.description": "Промпти, які використовуються командою /debug: видиме повідомлення користувача + приховані інструкції. Веде кероване дослідження першопричини — фіксує симптом, формує гіпотези, перевіряє їх по коду й підтверджує причину перш ніж пропонувати фікс.",
  "settings.magicPrompts.page.group.sessionWeigh.title": "Зважування варіантів",
  "settings.magicPrompts.page.group.sessionWeigh.description": "Промпти, які використовуються командою /weigh: видиме повідомлення користувача + приховані інструкції. Досліджує код, а тоді викладає 2-3 різні підходи з trade-offs і рекомендацією — без плану чи коду.",
  "settings.magicPrompts.page.group.sessionFusion.title": "Fusion",
  "settings.magicPrompts.page.group.sessionFusion.description": "Промпти для обʼєднання результатів multi-run в одну фінальну відповідь: видиме повідомлення користувача + приховані інструкції перед результатами джерел.",
