  'settings.piarium.pluginSettings.webAccess.routing.fallbackProviders': 'Упорядковані ідентифікатори постачальників, по одному в рядку. Першим запускається перший придатний.',
  'settings.piarium.pluginSettings.webAccess.routing.fallbackKinds': 'Помилки, що переводять маршрут далі: transient, quota та/або network.',
  'settings.piarium.pluginSettings.webAccess.tools.title': 'Загальнодоступні назви інструментів',
  'settings.piarium.pluginSettings.webAccess.tools.description': 'Назви мають бути унікальними, починатися з літери та містити не більш як 64 літери, цифри, підкреслення або дефіси.',
  'settings.piarium.pluginSettings.webAccess.providers.credentialDescription': 'Замасковане поле. Приймає літерал, $ENV_NAME / ${ENV_NAME} або надійне джерело !command.',
  'settings.piarium.pluginSettings.webAccess.providers.secretNote': 'Облікові дані тут не перевіряються й не потрапляють до зведень. Змінні середовища та джерела-команди обробляє розширення.',
  'settings.piarium.pluginSettings.webAccess.providers.title': 'Конфігурація постачальників',
  'settings.piarium.pluginSettings.webAccess.providers.description': 'Налаштовуйте лише постачальників, яких використовуєте. Exa доступний через шлях MCP без конфігурації, якщо прямий ключ не задано.',
  'settings.piarium.pluginSettings.webAccess.providers.editor': 'Постачальник',
  'settings.piarium.pluginSettings.webAccess.providers.serpdiveCost': 'Глибина отримання визначає вартість. krill — безкоштовне типове значення; mako та moby споживають кредити.',
  'settings.piarium.pluginSettings.webAccess.providers.firecrawlRisk': 'Свіже сканування дозволяє серверу Firecrawl виконувати вихідні запити. Вмикайте лише за наявності належної мережевої ізоляції.',
  'settings.piarium.pluginSettings.webAccess.curator.title': 'Сервер куратора',
  'settings.piarium.pluginSettings.webAccess.curator.description': 'Керуйте адресою прив’язки короткоживучого сервера перевірки та тим, чи відкриватиме Pi його URL автоматично.',
  'settings.piarium.pluginSettings.webAccess.curator.ignoredShape': 'Наявне значення curatorRemote має непідтримувану форму, тому плагін вважає його локальним. Вибір режиму тут замінює його.',
  'settings.piarium.pluginSettings.webAccess.curator.remoteBroadWarning': 'Віддалений куратор відкритий на всіх інтерфейсах через незашифрований HTTP. Його токен URL і відібраний вміст видно в мережі; краще вказати конкретну приватну адресу прив’язки.',
  'settings.piarium.pluginSettings.webAccess.curator.remoteWarning': 'Віддалений куратор використовує незашифрований HTTP і секретний токен URL. Тримайте URL приватним і прив’язуйте лише до довіреної мережі.',
  'settings.piarium.pluginSettings.webAccess.curator.remoteDescription': 'Локальний режим — безпечний типовий варіант. Похідний віддалений використовує ім’я хоста й прив’язується до 0.0.0.0; власний режим дає змогу вибрати обидва значення.',
  'settings.piarium.pluginSettings.webAccess.curator.mode.local': 'Лише локально · 127.0.0.1',
  'settings.piarium.pluginSettings.webAccess.curator.mode.derived': 'Віддалено · ім’я хоста / 0.0.0.0',
