  'settings.piarium.pluginSettings.webAccess.browser.cookieWarning': 'Доступ за згодою може читати бази cookie Chromium і викликати сховище паролів операційної системи. У вимкненому стані нічого не читається.',
  'settings.piarium.pluginSettings.webAccess.shortcuts.title': 'Комбінації Pi',
  'settings.piarium.pluginSettings.webAccess.shortcuts.description': 'Зміни комбінацій набувають чинності після перезавантаження сеансу під час збереження.',
  'settings.piarium.pluginSettings.webAccess.content.github.title': 'Репозиторії GitHub',
  'settings.piarium.pluginSettings.webAccess.content.github.description': 'Керуйте спеціалізацією локального клонування, порогом розміру, тайм-аутом і шляхом кешу сеансу.',
  'settings.piarium.pluginSettings.webAccess.content.media.title': 'YouTube, локальне відео та PDF',
  'settings.piarium.pluginSettings.webAccess.content.media.description': 'Вибирайте доступність функцій, моделі Gemini та обмеження розміру введення. Видобування кадрів і надалі залежить від ffmpeg та yt-dlp.',
  'settings.piarium.pluginSettings.webAccess.security.note': 'Ці елементи керування навмисно змінюють мережеву доступність. Piarium перевіряє їхню форму, але не послаблює й не замінює перевірки SSRF розширення.',
  'settings.piarium.pluginSettings.webAccess.security.domains.title': 'Політика доменів отримання',
  'settings.piarium.pluginSettings.webAccess.security.domains.description': 'Голі імена хостів відповідають собі та піддоменам. Заборона має перевагу над дозволом; порожній список дозволів пропускає будь-яке ім’я хоста, що проходить перевірки SSRF.',
  'settings.piarium.pluginSettings.webAccess.security.ssrf.title': 'Винятки SSRF і попередня перевірка проксі',
  'settings.piarium.pluginSettings.webAccess.security.ssrf.description': 'Додавайте лише вузькі діапазони CIDR, потрібні приватній службі або проксі fake-IP. Діапазони /0 залишаються недійсними.',
